package org.telegram.messenger;
import java.io.*;
import java.net.*;
import java.util.concurrent.*;
import java.util.function.Consumer;
import org.json.JSONObject;
import org.telegram.messenger.devgram.player.TrackQuery;

/** Resolve a permitted full provider stream, or use the exact local native track. No previews as full songs. */
public final class DevGramLyricsAudioSource {
 private static final ExecutorService IO=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"devgram-lyric-stream");t.setDaemon(true);return t;});
 private DevGramLyricsAudioSource(){}
 public static File local(int account,TrackQuery query){MessageObject playing=MediaController.getInstance().getPlayingMessageObject();TrackQuery actual=TrackQuery.forMessage(playing);if(actual==null||!same(query,actual))return null;File file=FileLoader.getInstance(account).getPathToMessage(playing.messageOwner);if(!file.isFile()&&playing.messageOwner.attachPath!=null&&!playing.messageOwner.attachPath.isEmpty())file=new File(playing.messageOwner.attachPath);return file.isFile()?file:null;}
 private static boolean same(TrackQuery a,TrackQuery b){return TrackQuery.normalize(a.title()).equals(TrackQuery.normalize(b.title()))&&TrackQuery.normalize(a.artist()).equals(TrackQuery.normalize(b.artist()))&&(a.duration()==0||b.duration()==0||Math.abs(a.duration()-b.duration())<=8);}
 public static void resolve(int account,TrackQuery query,long owner,String block,Consumer<File> callback){File nativeFile=local(account,query);if(nativeFile!=null){callback.accept(nativeFile);return;}if(owner==0||block==null||block.isEmpty()){callback.accept(null);return;}long uid=UserConfig.getInstance(account).getClientUserId();JSONObject body=new JSONObject();try{body.put("owner",owner).put("block",block).put("action","resolve");}catch(Exception ignored){}
  DevGramProfilePolicy.request(account,"studio/listen/state",body,(data,error)->{if(UserConfig.getInstance(account).getClientUserId()!=uid){callback.accept(null);return;}JSONObject stream=data==null?null:data.optJSONObject("stream"),track=data==null?null:data.optJSONObject("track");if(stream==null||track==null||stream.optBoolean("previewOnly")||!same(query,new TrackQuery(track.optString("artist"),track.optString("title",track.optString("track")),track.optString("album"),(int)(track.optLong("duration")/1000)))){callback.accept(null);return;}String url=stream.optString("url");IO.execute(()->{File file=null;try{File folder=new File(ApplicationLoader.applicationContext.getCacheDir(),"devgram-lyrics-audio");if(!folder.isDirectory()&&!folder.mkdirs())throw new IOException();file=File.createTempFile("track-",".bin",folder);fetch(url,file); }catch(Exception failure){if(file!=null)file.delete();file=null;}File result=file;AndroidUtilities.runOnUIThread(()->{if(UserConfig.getInstance(account).getClientUserId()!=uid){if(result!=null)result.delete();callback.accept(null);}else callback.accept(result);});});});
 }
 private static void fetch(String value,File target)throws IOException{URL url=new URL(value);for(int redirects=0;redirects<4;redirects++){if(!url.getProtocol().equals("https")||url.getUserInfo()!=null||url.getPort()!=-1&&url.getPort()!=443)throw new IOException("audio_url");for(InetAddress address:InetAddress.getAllByName(url.getHost()))if(address.isAnyLocalAddress()||address.isLoopbackAddress()||address.isSiteLocalAddress()||address.isLinkLocalAddress()||address.isMulticastAddress())throw new IOException("audio_host");HttpURLConnection connection=(HttpURLConnection)url.openConnection();try{connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(12000);connection.setReadTimeout(30000);int status=connection.getResponseCode();if(status>=300&&status<400){String location=connection.getHeaderField("Location");if(location==null)throw new IOException();url=new URL(url,location);continue;}if(status!=200||connection.getContentLengthLong()>32L*1024*1024)throw new IOException("audio_http");try(InputStream input=connection.getInputStream();OutputStream output=new FileOutputStream(target)){byte[] buffer=new byte[65536];int count;long size=0;while((count=input.read(buffer))!=-1){size+=count;if(size>32L*1024*1024)throw new IOException("audio_size");output.write(buffer,0,count);}}return;}finally{connection.disconnect();}}throw new IOException("audio_redirects");}
}
